combine(
        programRepository.getAll(),
        pathRepository.activePaths,
        userRepository.getUser(),
    ) { programs, activePaths, user ->
        val activePathIds = activePaths.map { it.id }.toSet()
        val enrolledId = programs.firstOrNull { it.isEnrolled }?.id
        val nonArchived = programs.filter { it.isActive }

        // Collapse each curated family (the same plan at Beginner/Intermediate/Advanced) down to the
        // single row matching the user's training experience — difficulty is auto-picked and never
        // shown. Day-count variants stay as separate families, so the user still chooses 3/4/5-day.
        val families = collapseByExperience(nonArchived, user.trainingExperience)

        val recommended: List<ProgramEntity>
        val other: List<ProgramEntity>
        if (activePathIds.isEmpty()) {
            recommended = emptyList()
            other = families.map { it.representative }
        } else {
            // Recommended = the family matches ALL active paths. Match against the family's union of
            // paths (not just the picked row) so a recommendation never disappears because the
            // auto-picked difficulty happens to drop a path the other levels carry.
            recommended = families
                .filter { fam -> activePathIds.all { it in fam.unionPathIds } }
                .map { it.representative }

            val recommendedIds = recommended.map { it.id }.toSet()
            other = families.map { it.representative }.filter { it.id !in recommendedIds }
        }

        ProgramsUiState(
            recommendedPrograms = recommended,
            otherPrograms = other,
            enrolledProgramId = enrolledId,
            hasActivePaths = activePathIds.isNotEmpty(),
            isOnMyOwnJourney = "path_self_directed" in activePathIds,
            isLoading = false,
        )
    }.stateIn

