combine(
        repository.getAll(),
        _tab,
        _query,
    ) { all, tab, query ->
        val filtered = all
            .filter { ex ->
                when (tab) {
                    ExerciseTab.ALL -> true
                    ExerciseTab.BUILT_IN -> !ex.isCustom
                    ExerciseTab.CUSTOM -> ex.isCustom
                    ExerciseTab.FAVORITES -> ex.isFavorite
                }
            }
            .filter { ex -> query.isBlank() || ex.name.contains(query, ignoreCase = true) }

        // "Never program" exercises live in their own collapsed section, out of the splits.
        val (excluded, active) = filtered.partition { it.isExcluded }

        // Group into split sections; favourites float to the top within each section.
        val grouped = active.groupBy { it.trainingSplitSection() }
        val sections = TrainingSplit.entries.mapNotNull { split ->
            val items = grouped[split]
                ?.sortedWith(compareByDescending<ExerciseEntity> { it.isFavorite }.thenBy { it.name })
                ?: return@mapNotNull null
            if (items.isEmpty()) null else split to items
        }

        ExercisesUiState(
            sections = sections,
            excluded = excluded.sortedBy { it.name },
            activeTab = tab,
            query = query,
            isLoading = false,
        )
    }.stateIn

